"""On-screen text in league terms: menus, setup, the international screens, calls, staff and scouting."""
import re

def apply(js, rep, resub, replace_function):
    A = lambda old, new: rep(js_[0], old, new, None)
    js_ = [js]
    def R(old, new, n=1):
        js_[0] = rep(js_[0], old, new, n)
    def RE(pat, new, n=None, flags=0):
        js_[0] = resub(js_[0], pat, new, n, pat[:30], flags)
    def F(name, src):
        js_[0] = replace_function(js_[0], name, src, name)

    # Names of things, everywhere.
    RE(r"Rugby World Cup", "Rugby League World Cup")
    RE(r"Rugby League League", "Rugby League")
    RE(r"Club World Cup", "World Club Series")
    RE(r"Union &amp; history", "Federation &amp; history")
    RE(r"Union & history", "Federation & history")
    RE(r"\bunions\b", "federations")
    RE(r"\bunion\b", "federation")
    RE(r"\bUnion\b(?! &)", "Federation")
    RE(r"Test rugby", "Test football")
    RE(r"\bclub rugby\b", "club football")
    RE(r"\bClub rugby\b", "Club football")
    RE(r"\bworld rugby\b", "rugby league")
    RE(r"biggest job in rugby", "biggest job in rugby league")
    RE(r"biggest jobs in rugby\b", "biggest jobs in rugby league")
    RE(r"Rugby manager · offline single player", "Rugby league manager · offline single player")
    RE(r"'Rugby news'", "'League news'")
    RE(r"Knockout rugby\.", "Finals football.")
    RE(r"more rugby", "more footy")
    RE(r"Regular rugby elsewhere", "Regular footy elsewhere")
    RE(r"talk rugby with", "talk footy with")
    RE(r"focus on rugby", "focus on footy")
    RE(r"without senior rugby", "without first-grade football")
    RE(r"Retire from rugby\?", "Retire from footy?")
    RE(r"Drop goal chance", "Field goal chance")
    RE(r"'Drop goal'", "'Field goal'")
    RE(r"Tries, conversions, penalties, drop goals", "Tries, conversions, penalty goals, field goals")

    # Live match labels and call titles.
    R("set:'Set piece',kick:'Kicking'", "set:'Restart',kick:'Kicking'")
    F('callTitle', CALL_TITLE)
    F('callWaitLine', CALL_WAIT)
    RE(r"^const MOMENT_N=\{.*?\};", lambda m: MOMENT_N, 1, re.M)
    # Prematch head to head.
    R("${unitRow('Set piece',U.setpiece,O.setpiece)}${unitRow('Forward pack',U.pack,O.pack)}${unitRow('Breakdown',U.breakdown,O.breakdown)}${unitRow('Backs attack',U.backs,O.backs)}",
      "${unitRow('Middle forwards',U.pack,O.pack)}${unitRow('Ruck speed',U.setpiece,O.setpiece)}${unitRow('Ruck control',U.breakdown,O.breakdown)}${unitRow('Edge attack',U.backs,O.backs)}")
    # Staff.
    R("defence:{n:'Defence coach',d:'Runs the defensive system and the breakdown.'},forwards:{n:'Forwards coach',d:'Scrum, lineout and maul.'}", "defence:{n:'Defence coach',d:'Runs the defensive line and the ruck.'},forwards:{n:'Forwards coach',d:'The middle: carries, play-the-ball speed and ruck control.'}")
    R("`Backs attack ${f(z)} · back three ${f(.6*z)} · kicking ${f(.5*z)}`", "`Edge attack ${f(z)} · yardage ${f(.6*z)} · kicking ${f(.5*z)}`")
    R("[`Learning defence and breakdown plans ${pct(.3*z)}`,`Defence ${f(z)} · breakdown ${f(.7*z)} · discipline ${f(.6*z)}`]", "[`Learning defence and ruck plans ${pct(.3*z)}`,`Defence ${f(z)} · ruck control ${f(.7*z)} · discipline ${f(.6*z)}`]")
    R("[`Set piece ${f(1.3*z)} · forward pack ${f(.8*z)}`]", "[`Ruck speed ${f(1.3*z)} · middle forwards ${f(.8*z)}`]")
    # Scouting and tactics text.
    R("<b>Counters.</b> A forward-led attack beats a drift defence and a side that fans out, but a strong breakdown unit that competes will slow it down. A wide attack beats a drifting or weak rush defence, but a strong rush defence or a side that fans out shuts it down. Kicking for territory punishes a rush defence and poor discipline, but a quick back three counter-attacks loose kicks. The possession game rewards fitness, but a strong breakdown steals turnovers.</p><p><b>Playing to your strengths.</b> Each option leans on one part of your team: the forward pack, the back line, your kickers, your defence or your breakdown unit.",
      "<b>Counters.</b> An attack through the middle beats a slide defence and a side that gets back early, but strong ruck control that wrestles will slow it down. An edge attack beats a slide or weak line speed, but strong up-and-in defence or extra numbers in the line shut it down. Kicking for field position punishes line speed and poor discipline, but a quick back three runs loose kicks back. Ball in hand rewards fitness, but a strong ruck wrestle forces errors.</p><p><b>Playing to your strengths.</b> Each option leans on one part of your team: the middle forwards, the edges, your kickers, your defence or your ruck control.")
    R("Every player has a style, such as Jackal, Ball carrier, Game manager or Finisher, and each style suits one or two options.", "Every player has a style, such as Metre-eater, Ball-playing lock, Game manager or Finisher, and each style suits one or two options.")
    R("title:'Stop their forward carries',detail:`They play through their pack, rated ${v(O.pack)} against your ${v(U.pack)}. Drifting or fanning out leaves gaps close to the ruck; competing slows them only if your breakdown unit (${v(U.breakdown)}) can match their pack.`",
      "title:'Stop their middle',detail:`They play through their middle forwards, rated ${v(O.pack)} against your ${v(U.pack)}. Sliding or getting back early leaves soft shoulders close to the ruck; wrestling slows them only if your ruck control (${v(U.breakdown)}) can match their pack.`")
    R("title:'Shut down their back line',detail:`They move the ball wide early, with a back line rated ${v(O.backs)} against your ${v(U.backs)}. A rush defence stops them only if your defence (${v(U.defence)}) is good enough; fanning out and drifting are the safer answers.`",
      "title:'Shut down their edges',detail:`They go to the edges early, with edge attack rated ${v(O.backs)} against your ${v(U.backs)}. Up-and-in line speed stops them only if your defence (${v(U.defence)}) is good enough; numbers in the line and a slide are the safer answers.`")
    R("title:'Win the kicking battle',detail:`They kick for territory, with kicking rated ${v(O.kicking)} against your ${v(U.kicking)}. Rushing up invites kicks in behind; a quick back three (yours: ${v(U.backThree)}) punishes loose kicks.`",
      "title:'Win the kicking battle',detail:`They kick for field position, with kicking rated ${v(O.kicking)} against your ${v(U.kicking)}. Rushing up invites kicks in behind; a strong back three (yours: ${v(U.backThree)}) runs loose kicks back.`")
    R("title:'Slow their phase play',detail:`They keep the ball and build phases. Competing at the breakdown wins turnovers if your breakdown unit (${v(U.breakdown)}) is strong; a good rush defence cuts phases short.`",
      "title:'Slow their play-the-ball',detail:`They keep the ball in hand and play fast. Wrestling at the ruck forces errors if your ruck control (${v(U.breakdown)}) is strong; good line speed kills their momentum.`")
    # Weather advice.
    R("makes goal kicking and lineout throwing harder.", "makes goal kicking and the long kicking game harder.")
    R("'Firm, fast pitch: it suits pace and width, and the scrum stays stable.'", "'Firm, fast pitch: it suits pace, width and a quick play-the-ball.'")
    R("heavy underfoot, fewer line breaks and a scrappy scrum. It favours the stronger pack and a direct game.", "heavy underfoot, fewer line breaks and a slower ruck. It favours the stronger middle and a direct game.")
    # International screens.
    F('intlCompetitionHTML', INTL_COMP)
    js_[0] = resub(js_[0], r"const about=\{sixn:.*?\}\[c\];", lambda m: "const about={pacc:'Australia, New Zealand, Tonga and Samoa play each other once. The top of the table takes the Pacific Cup.',pacc3:'New Zealand, Tonga and Samoa play each other once while Australia tour for the Ashes.',pacb:'Papua New Guinea, Fiji and the Cook Islands play each other once for the Pacific Bowl.',euro:'France, Wales, Ireland and Scotland play each other once for the European Championship.',ashes:'England and Australia play a three-Test series. Win two to take the Ashes.'}[c]||'';", 1, 'about', re.S)
    R(" Four points for a win, two for a draw, a bonus point for four tries or for losing by seven or fewer.</p>", " Two points for a win, one for a draw.</p>")
    F('intlWCBody', INTL_WC)
    R("Test friendlies fill each window for every nation without a competition in it: Spring Tests during the Six Nations, September Tests alongside the Rugby Championship, summer tours in July and the Autumn Nations Series in November in years without a Nations Championship, and warm-ups before a World Cup.", "Test friendlies fill each window for every nation without a competition in it: the mid-season Tests in June, and end-of-year Tests for nations outside the Pacific Championships, the Pacific Bowl, the European Championship and the Ashes.")
    F('intlTrophyMetrics', TROPHIES)
    R("The rankings decide the World Cup pool draw and what your federation expects of you.", "The rankings decide the World Cup groups and what your federation expects of you.")
    R("<p>For the World Cup draw the 24 nations are split into four bands of six by ranking, and each pool takes one nation from each band. The host goes in Pool A.</p>", "<p>For the World Cup the top ten nations qualify (the host always does). Group A takes the two highest-ranked and the two lowest-ranked; Groups B and C share the middle six and play each other.</p>")
    F('intlSetupHTML', INTL_SETUP)
    R("The World Cup and the Nations Championship count most, then the Six Nations and the Rugby Championship; Test windows count least. Trophies and promotion count for a lot, relegation hurts.", "The World Cup counts most, then the Pacific Championships, the Ashes and the European Championship; Test windows count least. Trophies count for a lot.")
    R("(f.place===0?(f.tier===1?'Nations Championship final':'Nations Cup final'):`${ordinal(f.place*2+1)}-place play-off`)", "(`${ordinal(f.place*2+1)}-place play-off`)")
    R("const eyebrow=wc?`Rugby League World Cup · ${esc(displayTeam(s.wcHost))}${s.phase!=='Selection'&&poolOf(s.team,s)?' · Po", "const eyebrow=wc?`Rugby League World Cup · ${esc(displayTeam(s.wcHost))}${s.phase!=='Selection'&&poolOf(s.team,s)?' · Gro")
    # Hero and player goals.
    R("['tier1','Top table','Coach a Nations Championship nation']", "['tier1','Top table','Coach a Tier 1 Test nation']")
    R("['league','Domestic champions','Win Super Rugby, the URC or the Premiership'],['hemi','Hemisphere kings','Win the Six Nations or the Rugby Championship'],['nc','Nations champions','Win the Nations Championship'],['cwc','Best club on the planet','Win the World Club Series']", "['league','Premiers','Win the NRL or Super League Grand Final'],['hemi','Pacific kings','Win the Pacific Championships, the Ashes or the European Championship'],['nc','Golden point','Win a match in golden point'],['cwc','Best club on the planet','Win the World Club Series']")
    R("if(T(/^(Six Nations|Rugby Championship)$/))got('hemi');if(T(/^Nations Championship$/))got('nc');", "if(T(/^(Pacific Championships|Ashes|European Championship)$/))got('hemi');if(s.results.some(r=>r.extra&&r.winner===s.team))got('nc');")
    R("['hemi','Six Nations or Rugby Championship','Win one with your country']", "['hemi','Pacific champion','Win the Pacific Championships, the Ashes or the European Championship']")
    R("['lions','British & Irish Lion','Tour with the Lions']", "['lions','State of Origin','Play State of Origin']")
    R("if(T(/^(Six Nations|Rugby Championship)$/))got('hemi');if(T(/^Rugby League World Cup$/))got('wc');if(P.lions)got('lions');", "if(T(/^(Pacific Championships|Ashes|European Championship)$/))got('hemi');if(T(/^Rugby League World Cup$/))got('wc');if((proMeOf(s)?.og||0)>0)got('lions');")
    R("caps, trophies, the Lions, a big move.", "caps, trophies, Origin, a big move.")
    # Menu, setup and the tournaments.
    F('menuHTML', MENU)
    F('setupHTML', SETUP)
    F('clubWorldCupSetupHTML', CWC_SETUP)
    js = js_[0]
    return js

CALL_TITLE = r"""function callTitle(M,C){const X=M.t[C.side],lead=engLead(M,X),rem=Math.max(0,M.end-C.m);if(C.type==='pen'){if(!C.clutch)return C.cap?(C.inRange?'Penalty in range, captain':'Penalty in their half, captain'):C.inRange?'Penalty in range. Your call.':'Penalty. Your call.';return !C.inRange?'One last chance from deep':lead===0?'Two points to win it?':lead>=-2?'Two to level it, or go for the win?':'The two, or touch and a fresh set?'}
 if(C.type==='dg')return lead===0?(M.extra?'Golden point: field goal?':'Field goal to win it?'):lead===-1?'Field goal to level it?':'Field goal, or go for the try?';if(C.type==='restart')return 'Kick-off: go short?';if(C.type==='lt')return 'Last tackle, their twenty';if(C.type==='lo')return C.far?'Fresh set in their half':'Fresh set on their line';if(C.type==='sc')return 'Scrum feed, their end';if(C.type==='bench')return 'Time for the interchange?';if(C.type==='binThem')return C.red?'They are down to twelve':'They are down to twelve for ten minutes';if(C.type==='binUs')return 'You are down to twelve';if(C.type==='inj')return `${player(C.id)?.name||'A player'} cannot carry on`;if(C.type==='k5022')return 'Last tackle in your own half';if(C.type==='jackal')return lead<0?'They are camped on your line':'The ruck battle';if(C.type==='pen2')return 'Penalty! What now?';if(C.type==='final')return lead>=-1?'Last set: win it or draw it?':'Last set: you need a try';if(C.type==='close')return 'Close it out';if(C.type==='defend')return 'Their last set';return 'Your call'}"""

CALL_WAIT = r"""function callWaitLine(C,c){return C.type==='pen'||C.type==='pk'||C.type==='tk'?(c==='posts'||C.type==='pk'||C.type==='tk'?'The kick is away…':c==='tap'?'Tap and go…':'Kicked for touch…'):C.type==='dg'?(c==='drop'?'He drops back into the pocket…':'Tackle after tackle…'):C.type==='restart'?(c==='short'?'The kick-off goes short…':'Kicked long…'):C.type==='lt'?(c==='bomb'?'It goes up…':c==='grubber'?'The grubber goes in…':'They shift it on the last…'):C.type==='jackal'?(c==='jackal'?'Bodies on him…':c==='counter'?'Two in, one strips…':'Get back, get back…'):C.type==='pen2'?(c==='posts'?'The kick is away…':c==='touch'?'Kicked to touch…':'Quick tap…'):C.type==='lo'?'Tap restart, six fresh tackles…':C.type==='sc'?'The scrum packs down…':C.type==='final'?(c==='drop'?'He drops back into the pocket…':c==='wide'?'They spread it wide…':'Hit-up after hit-up…'):C.type==='close'?(c==='kick'?'Kicked long…':c==='score'?'They go for the kill…':'Hit-up, hit-up, the clock ticking…'):C.type==='defend'?(c==='cynical'?'Lying all over the ruck…':c==='rush'?'The line jams in…':'Hold, hold, hold…'):'…'}"""

MOMENT_N = r"""const MOMENT_N={break:'Line break',cover:'Last line of defence',ruck:'Ruck battle',catch:'Bomb coming down',carry:'Five metres out',dgPro:'Field goal chance',throw:'Dummy-half chance',scrum:'Kick pressure',box:'Last tackle kick',intercept:'Intercept chance',k5022:'40/20 chance',pk:'Kick at goal',tk:'Kick for touch',pen:'Penalty',pen2:'Penalty',lo:'Fresh set',sc:'Scrum feed',dg:'Field goal',lt:'Last tackle',final:'Last set',close:'Closing it out',defend:'Their last set',restart:'Kick-off',maulD:'Goal-line stand',jackal:'Ruck battle',k5022c:'40/20'};"""

INTL_COMP = r"""function intlCompetitionHTML(s){const w=curWin(s),cur=w?winCompOf(s.team,w,s):'tests',cal=buildIntlCalendar(s.year),list=[...new Set([...cal.flatMap(x=>x.comps||[]),'tests'])],key=s.year+':'+s.calIdx;if(intlCompKey!==key||!list.includes(intlCompView)){intlCompKey=key;intlCompView=list.includes(cur)?cur:list[0]}const v=intlCompView,label=c=>c==='tests'?'Tests':c==='wc'?'World Cup':INTL_COMPS[c].name;
 const body=v==='wc'?intlWCBody(s):v==='tests'?intlTestsBody(s):intlLeagueBody(s,v);
 return `${sectionHeader(`Competitions / ${s.year}`,'The international season.',`${yearKind(s.year)}: ${cal.map(x=>`${x.name} (${x.when})`).join(', ')}.`)}<div class="tabs comp-tabs intl-comp-tabs" role="group" aria-label="Competition">${list.map(c=>`<button class="${v===c?'active':'ghost'} small" data-act="intl-comp" data-comp="${c}" aria-pressed="${v===c}">${esc(label(c))}${c===cur&&s.phase!=='Complete'?'<span class="now-dot" title="Your competition now"></span>':''}</button>`).join('')}</div>${body}`}"""

INTL_WC = r"""function intlWCBody(s){if(s.comp!=='wc'||!s.intlPools){const y=nextWC(s.year);return `<section class="card"><h2>Rugby League World Cup ${y}</h2><p class="sub muted">${y===s.year?`October and November in ${esc(displayTeam(wcHost(y)))}. The top ten nations in the world rankings qualify: Group A plays a round robin, and Groups B and C play each other on one combined table. The top two from each go through to the semi-finals.`:`The next World Cup is in ${y}, hosted by ${esc(displayTeam(wcHost(y)))}.`}</p></section>`}
 const G=wcGroups(poolsFor(s));return `<p class="tiny muted hint">Hosted by ${esc(displayTeam(s.wcHost))}. Group A plays a round robin; Groups B and C play each other on one combined table. The top two of Group A and of Groups B and C meet in the semi-finals.</p><div class="two">${Object.entries(G).map(([k,teams])=>`<section class="card"><h3>${k.length>1?'GROUPS '+esc(k)+' · combined table':'GROUP '+esc(k)}</h3>${tableHTML(teams,true)}</section>`).join('')}</div>${s.pending?.length&&knockoutPhase(s)?`<h2 style="margin-top:24px">${esc(s.phase)}</h2><div class="bracket">${s.pending.map(f=>`<div class="mini-match"><div><b>${esc(displayTeam(f.a))}</b><span>—</span></div><div><b>${esc(displayTeam(f.b))}</b><span>—</span></div></div>`).join('')}</div>`:''}${(s.knockouts||[]).map(st=>`<h3 style="margin-top:22px">${esc(st.stage)}</h3><div class="bracket">${st.reports.map(r=>`<div class="mini-match"><div><span>${esc(displayTeam(r.a))}</span><b>${r.x}</b></div><div><span>${esc(displayTeam(r.b))}</span><b>${r.y}</b></div></div>`).join('')}</div>`).join('')}`}"""

TROPHIES = r"""function intlTrophyMetrics(s,h){const won=c=>h.filter(x=>x.comp===c&&x.trophy).length,T=s.team,pac=['Australia','New Zealand','Tonga','Samoa'].includes(T),ashes=(s.honours||[]).filter(x=>x.comp==='ashes'&&x.champion===T).length;return [['World Cups',won('wc'),true],['Pacific Championships',won('pacc')+won('pacc3'),pac],['Pacific Bowls',won('pacb'),INTL_COMPS.pacb.teams.includes(T)],['European Championships',won('euro'),INTL_COMPS.euro.teams.includes(T)],['Ashes series',ashes,['England','Australia'].includes(T)]].filter(([,n,show])=>show||n>0).map(([l,n])=>metric(l,n,'Won as head coach')).join('')}"""

INTL_SETUP = r"""function intlSetupHTML(){const tmp={players:DB.players},lad=NATIONS.map(n=>({n,str:natStrength(n,tmp)})).sort((a,b)=>b.str-a.str),tier=n=>TIER_NAME[tierOf(n,{confs:NC_START})];if(!NATIONS.includes(setupTeam))setupTeam='Australia';
 const comp=n=>['pacc','pacb','euro'].map(c=>INTL_COMPS[c]).find(c=>c.teams.includes(n))?.name||'end-of-year Tests';
 return `${sectionHeader('Career · International','Build a nation over the years.','Take charge of a national team for as long as the federation keeps you. Every June brings the mid-season Tests. Every October and November brings the Pacific Championships, the Pacific Bowl and the European Championship, with the Ashes between England and Australia every four years from 2029, and Tests for everyone else. The World Cup comes round every four years, starting with 2026 in Australia. Between seasons players age, develop and retire, and new talent comes through.')}${setupTabsHTML()}<div class="team-grid">${lad.map(({n},i)=>`<button class="team-choice ${setupTeam===n?'chosen':''}" data-act="choose-team" data-team="${esc(n)}">${mark(n)}<span class="name">${esc(displayTeam(n))}</span><small>About #${i+1} in the world · ${tier(n)}</small></button>`).join('')}</div><div class="modebar"><div><b>${esc(displayTeam(setupTeam))}</b><small>2026: ${Object.values(POOLS).flat().includes(setupTeam)?'Rugby League World Cup in Australia':'mid-season and end-of-year Tests'} · every year: ${esc(comp(setupTeam))}</small></div><button class="primary" data-act="start-career">Start →</button></div>${saves.intlcareer?'<p class="tiny muted">This replaces your existing international career, after confirmation. Your other careers are kept.</p>':''}`}"""

MENU = r"""function menuHTML(){const saved=SAVE_SLOTS.filter(m=>saves[m]),kind=m=>m==='international'||m==='clubworldcup'?'Tournament':m==='hero'?`Hero career · ${saves.hero.hero?.name||''}`:m==='pro'?`Player career · ${saves.pro.pro?.name||''}`:'Career';
 const card=(attrs,kicker,title,desc,meta,going)=>`<button class="entry" ${attrs}><div class="flex between"><span class="eyebrow">${kicker}</span><span class="arrow">↗</span></div><h2>${title}</h2><span class="muted sub hint">${desc}</span><span class="entry-meta">${meta}${going?' · <b>in progress</b>':''}</span></button>`;
 return `<div class="start-wrap">${saved.length?`<section class="continue"><div class="eyebrow">Continue</div>${saved.map(m=>{const s=saves[m];return `<div class="modebar">${mark(s.team)}<div style="flex:1;min-width:0"><b>${esc(displayTeam(s.team))}</b><small>${kind(m)} · ${esc(careerLine(s))}</small></div><button class="primary" data-act="resume" data-mode="${m}">Continue →</button></div>`}).join('')}</section>`:''}<span class="pill">Rugby league manager · offline single player</span><h1 class="cover">Six again.<br><em>Your call.</em></h1><p class="muted hint" style="max-width:620px">Build a squad of real players. Follow their form, pick your 17, set the game plan, survive Origin, manage the cap and give emerging talent a chance to shine.</p><div class="hint">${menuFeaturesHTML()}</div>
 <section class="menu-group"><div class="menu-head"><div><div class="eyebrow">Careers</div><h2>Build something that lasts</h2></div><p class="muted sub hint">Season after season: players age, develop and retire, and your board or federation judges every result.</p></div><div class="two">${Object.entries(LEAGUES).map(([key,l])=>card(`data-act="setup" data-mode="club" data-league="${key}"`,'Club career',l.name,`${l.teams.length} clubs · ${l.games} games each · top ${l.playoffs} play the finals. Contracts, transfers and the salary cap.${key==='nrl'?' State of Origin takes your stars mid-season.':''}`,'2026 squads',!!saves[saveSlot(key)])).join('')}${card('data-act="setup" data-mode="intlcareer"','International career','National team coach','Pick a country and run its year: mid-season Tests, the Pacific Championships or the European Championship, the Ashes every four years and the World Cup. The federation sets your objectives.','Test football all year round',!!saves.intlcareer)}${card('data-act="setup" data-mode="hero"','Hero career','From nobody to the top job','Start at one of the weakest clubs or nations in the game and climb one ladder of every job in rugby league, club and country, as offers come in over the years.','Clubs and nations · one career',!!saves.hero)}${card('data-act="setup" data-mode="pro"','Player career','From development contract to legend','Create a player and live his career: earn your spot, train, make the big plays in your own moments, win caps and decide where you play.','One player · club and country',!!saves.pro)}</div></section>
 <section class="menu-group"><div class="menu-head"><div><div class="eyebrow">Tournaments</div><h2>One shot at glory</h2></div><p class="muted sub hint">A single competition from the first kick-off to the final. No contracts, no next season.</p></div><div class="two">${card('data-act="setup" data-mode="international"','Tournament','Rugby League World Cup 2026','Choose your country, name your 24 and take on the world in Australia, in the real 2026 format: Group A, and Groups B and C playing each other.','10 nations · semi-finals and final',!!saves.international)}${card('data-act="setup" data-mode="clubworldcup"','Tournament','World Club Series','A fictional global cup for the top 16 NRL and Super League clubs, by world ranking.','16 clubs · four pools',!!saves.clubworldcup)}</div></section>
 <div class="grid hint" style="margin-top:24px">${metric('Playable clubs',CLUBS.length,'NRL and Super League')}${metric('Players',DB.players.length.toLocaleString(),'One connected market')}${metric('National teams',NATIONS.length,'One world ranking')}</div><p class="footer-note hint">Roster snapshot: ${esc(DB.meta.checked)}. Squads are compiled from 2026 public reporting and may contain mistakes; fictional depth players are marked as such. Ratings, contracts, tactics, playing styles and values are game estimates. World Cup hosts after 2034 are fictional.</p></div>`}"""

SETUP = r"""function setupHTML(){if(setupMode==='pro')return proSetupHTML();if(setupMode==='hero')return heroSetupHTML();if(setupMode==='clubworldcup')return clubWorldCupSetupHTML();if(setupMode==='intlcareer')return intlSetupHTML();const intl=setupMode==='international',l=LEAGUES[setupLeague],teams=intl?Object.values(POOLS).flat():l.teams,slot=intl?'international':saveSlot(setupLeague);if(intl&&!teams.includes(setupTeam))setupTeam='Australia';return `${sectionHeader(intl?'Tournament · Rugby League World Cup 2026':'Career · '+l.name,intl?'Your country. Your 24.':'Choose your club.',intl?'A single World Cup in Australia. The other nations select automatically; you decide who earns a place in your final squad. For a multi-year national team career, choose International under Careers.':'Season after season of selection decisions, contract talks and a changing transfer market.')}${setupTabsHTML()}<div class="team-grid">${teams.map(t=>{const list=DB.players.filter(p=>intl?p.nation===t:p.club===t);return `<button class="team-choice ${setupTeam===t?'chosen':''}" data-act="choose-team" data-team="${esc(t)}">${mark(t)}<span class="name">${esc(displayTeam(t))}</span><small>${list.length} players ${intl?'in national pool':'in the squad'}${intl?' · Group '+poolOf(t):''}</small>${!intl&&setupMode==='club'?setupOutlookHTML(t,teams,LEAGUES[setupLeague]?.playoffs||8):''}</button>`}).join('')}</div><div class="modebar"><div><b>${esc(displayTeam(setupTeam))}</b><small>${intl?'Submit 24, then choose your matchday 17.':`${l.games} games · top ${l.playoffs} play the finals`}</small></div><button class="primary" data-act="start-career">Start →</button></div>${saves[slot]?'<p class="tiny muted">This replaces only the existing career for this league, after confirmation. Other careers are kept.</p>':''}`}"""

CWC_SETUP = r"""function clubWorldCupSetupHTML(){const rankings=clubWorldRankings(),qualifiers=rankings.slice(0,CLUB_WORLD_CUP_SIZE);if(!qualifiers.some(x=>x.team===setupTeam))setupTeam=qualifiers[0].team;return `${sectionHeader('Tournament · World Club Series','The best clubs on the planet, in one tournament.','A fictional global cup pooling every NRL and Super League club. Entirely optional — start it if you want it, and it never touches your domestic careers.')}${setupTabsHTML()}<section class="card"><h2>World Ranking</h2><p class="tiny muted hint">A game estimate blending each club's squad strength and star power — not an official ranking. The top ${CLUB_WORLD_CUP_SIZE} qualify.</p><div class="table-wrap"><table><tr><th>#</th><th>Club</th><th>Rating</th><th>Status</th></tr>${rankings.map((r,i)=>`<tr class="${r.team===setupTeam?'me':''}"><td>${i+1}</td><td>${esc(displayTeam(r.team))}</td><td>${r.rating}</td><td>${i<CLUB_WORLD_CUP_SIZE?'<span class="chip good">Qualified</span>':'<span class="chip bad">Did not qualify</span>'}</td></tr>`).join('')}</table></div></section><div class="team-grid">${qualifiers.map(({team:t,rating},i)=>{const list=DB.players.filter(p=>p.club===t);return `<button class="team-choice ${setupTeam===t?'chosen':''}" data-act="choose-team" data-team="${esc(t)}">${mark(t)}<span class="name">${esc(displayTeam(t))}</span><small>World ranking ${i+1} · ${list.length} players · rating ${rating}</small></button>`}).join('')}</div><div class="modebar"><div><b>${esc(displayTeam(setupTeam))}</b><small>Four pools of four · quarter-finals, semi-finals and a neutral-venue Grand Final</small></div><button class="primary" data-act="start-career">Start →</button></div>${saves.clubworldcup?'<p class="tiny muted">Starting a new World Club Series replaces your existing one, after confirmation.</p>':''}`}"""
